// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(this));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        vm.prank(caller);
        try c.withdrawAll(caller) { } catch { }
        bool balanceZero = address(c).balance == 0;
        bool isOwner = caller == address(this);
        assertTrue(balanceZero ? isOwner : !balanceZero);
    }
}
